body.script:
// --- 1. Scene, Camera, Renderer Setup ---
const container = document.getElementById('viewport-container');
const canvas = document.getElementById('three-canvas');
const pinsContainer = document.getElementById('pins-container');

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x13161c);

const camera = new THREE.PerspectiveCamera(42, container.clientWidth / container.clientHeight, 0.1, 100);
camera.position.set(2.8, 1.6, 2.2);

const renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true, preserveDrawingBuffer: true });
renderer.setSize(container.clientWidth, container.clientHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.localClippingEnabled = true;

const controls = new THREE.OrbitControls(camera, canvas);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 0.95, 0);
controls.maxPolarAngle = Math.PI * 0.52;
controls.minDistance = 1.2;
controls.maxDistance = 8.0;

// --- 2. Lighting Setup ---
const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
scene.add(ambientLight);

const mainLight = new THREE.DirectionalLight(0xfff7ea, 1.2);
mainLight.castShadow = true;
mainLight.shadow.mapSize.width = 2048;
mainLight.shadow.mapSize.height = 2048;
mainLight.shadow.bias = -0.0005;
mainLight.shadow.camera.near = 0.5;
mainLight.shadow.camera.far = 15;
mainLight.shadow.camera.left = -2.5;
mainLight.shadow.camera.right = 2.5;
mainLight.shadow.camera.top = 2.5;
mainLight.shadow.camera.bottom = -1.5;
scene.add(mainLight);

const fillLight = new THREE.DirectionalLight(0xb4c8e1, 0.35);
fillLight.position.set(-2, 1.5, -2);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xffffff, 0.4);
rimLight.position.set(0, 3, -3);
scene.add(rimLight);

function updateLightPosition() {
  const az = parseFloat(document.getElementById('light-azimuth').value) * Math.PI / 180;
  const el = parseFloat(document.getElementById('light-elevation').value) * Math.PI / 180;
  const radius = 5.0;
  const x = radius * Math.cos(el) * Math.sin(az);
  const y = radius * Math.sin(el);
  const z = radius * Math.cos(el) * Math.cos(az);
  mainLight.position.set(x, y, z);
}
updateLightPosition();

// --- 3. Slicing Plane ---
const clipPlane = new THREE.Plane(new THREE.Vector3(0, -1, 0), 1.2);
renderer.clippingPlanes = [];

// --- 4. Material Definitions ---
function createFurTexture() {
  const size = 512;
  const texCanvas = document.createElement('canvas');
  texCanvas.width = size;
  texCanvas.height = size;
  const ctx = texCanvas.getContext('2d');

  ctx.fillStyle = '#8a8e94';
  ctx.fillRect(0, 0, size, size);

  for (let i = 0; i < 60000; i++) {
    const x = Math.random() * size;
    const y = Math.random() * size;
    const v = Math.random();
    if (v < 0.35) {
      ctx.fillStyle = 'rgba(20, 22, 25, 0.4)';
    } else if (v < 0.7) {
      ctx.fillStyle = 'rgba(240, 242, 245, 0.45)';
    } else {
      ctx.fillStyle = 'rgba(110, 114, 120, 0.35)';
    }
    ctx.fillRect(x, y, 1.5, 2.5);
  }
  const tex = new THREE.CanvasTexture(texCanvas);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(4, 4);
  return tex;
}

const furMap = createFurTexture();

const materials = {
  chinchilla: {
    body: new THREE.MeshStandardMaterial({
      map: furMap,
      color: 0x82878e,
      roughness: 0.85,
      metalness: 0.05,
      clippingPlanes: [clipPlane],
      clipShadows: true
    }),
    chest: new THREE.MeshStandardMaterial({
      color: 0xdcdde0,
      roughness: 0.9,
      clippingPlanes: [clipPlane]
    }),
    ears: new THREE.MeshStandardMaterial({
      map: furMap,
      color: 0x767b82,
      roughness: 0.8,
      clippingPlanes: [clipPlane]
    }),
    earInner: new THREE.MeshStandardMaterial({
      color: 0xdfc9c2,
      roughness: 0.85,
      clippingPlanes: [clipPlane]
    }),
    earTip: new THREE.MeshStandardMaterial({
      color: 0x222428,
      roughness: 0.85,
      clippingPlanes: [clipPlane]
    }),
    eye: new THREE.MeshStandardMaterial({
      color: 0x050508,
      roughness: 0.08,
      metalness: 0.9,
      clippingPlanes: [clipPlane]
    }),
    eyeRing: new THREE.MeshStandardMaterial({
      color: 0xd6d8dc,
      roughness: 0.9,
      clippingPlanes: [clipPlane]
    }),
    nose: new THREE.MeshStandardMaterial({
      color: 0x9e8884,
      roughness: 0.7,
      clippingPlanes: [clipPlane]
    }),
    paws: new THREE.MeshStandardMaterial({
      color: 0xdcdfe4,
      roughness: 0.9,
      clippingPlanes: [clipPlane]
    })
  },
  clay: new THREE.MeshStandardMaterial({
    color: 0x8e929a,
    roughness: 0.65,
    metalness: 0.08,
    clippingPlanes: [clipPlane],
    clipShadows: true
  }),
  terracotta: new THREE.MeshStandardMaterial({
    color: 0xb56345,
    roughness: 0.72,
    metalness: 0.05,
    clippingPlanes: [clipPlane],
    clipShadows: true
  }),
  paperclay: new THREE.MeshStandardMaterial({
    color: 0xe8e6e1,
    roughness: 0.78,
    metalness: 0.02,
    clippingPlanes: [clipPlane],
    clipShadows: true
  }),
  blocking: {
    head: new THREE.MeshStandardMaterial({ color: 0xffcc33, roughness: 0.5, clippingPlanes: [clipPlane] }),
    cheeks: new THREE.MeshStandardMaterial({ color: 0xff9933, roughness: 0.5, clippingPlanes: [clipPlane] }),
    ears: new THREE.MeshStandardMaterial({ color: 0xff5577, roughness: 0.5, clippingPlanes: [clipPlane] }),
    torso: new THREE.MeshStandardMaterial({ color: 0x3399ee, roughness: 0.5, clippingPlanes: [clipPlane] }),
    thighs: new THREE.MeshStandardMaterial({ color: 0x22cc77, roughness: 0.5, clippingPlanes: [clipPlane] }),
    frontLegs: new THREE.MeshStandardMaterial({ color: 0x9955dd, roughness: 0.5, clippingPlanes: [clipPlane] }),
    paws: new THREE.MeshStandardMaterial({ color: 0x7744aa, roughness: 0.5, clippingPlanes: [clipPlane] }),
    hindFeet: new THREE.MeshStandardMaterial({ color: 0x1188bb, roughness: 0.5, clippingPlanes: [clipPlane] }),
    tail: new THREE.MeshStandardMaterial({ color: 0xff77aa, roughness: 0.5, clippingPlanes: [clipPlane] }),
    dewlap: new THREE.MeshStandardMaterial({ color: 0x55bbcc, roughness: 0.5, clippingPlanes: [clipPlane] })
  }
};

// --- 5. Construct 3D Model ---
const rabbitGroup = new THREE.Group();
scene.add(rabbitGroup);

const meshCatalog = {
  head: [],
  cheeks: [],
  ears: [],
  earInner: [],
  earTip: [],
  eyes: [],
  eyeRings: [],
  nose: [],
  dewlap: [],
  torso: [],
  chest: [],
  thighs: [],
  frontLegs: [],
  frontPaws: [],
  hindFeet: [],
  tail: []
};

// Torso with C-curve
function createTorsoMesh() {
  const geom = new THREE.SphereGeometry(1.0, 36, 28);
  const pos = geom.attributes.position;

  for (let i = 0; i < pos.count; i++) {
    let x = pos.getX(i);
    let y = pos.getY(i);
    let z = pos.getZ(i);

    let normY = (y + 1) * 0.5;
    let spineArch = Math.sin(normY * Math.PI) * 0.45;
    z += (normY > 0.4 ? -spineArch * 0.9 : spineArch * 0.5);

    let widthScale = 0.85 + (1.0 - normY) * 0.45;
    x *= widthScale;

    if (normY < 0.15) {
      y = -0.85 + normY * 0.1;
    }

    pos.setXYZ(i, x * 1.15, (y + 0.85) * 1.05 + 0.1, z * 1.25);
  }
  geom.computeVertexNormals();

  const mesh = new THREE.Mesh(geom, materials.chinchilla.body);
  mesh.position.set(0, 0, -0.1);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  rabbitGroup.add(mesh);
  meshCatalog.torso.push(mesh);
  return mesh;
}
createTorsoMesh();

// Chest fluff
const chestGeom = new THREE.SphereGeometry(0.55, 24, 20);
chestGeom.scale(1.0, 1.2, 0.75);
const chestMesh = new THREE.Mesh(chestGeom, materials.chinchilla.chest);
chestMesh.position.set(0, 0.9, 0.48);
chestMesh.rotation.x = -0.2;
chestMesh.castShadow = true;
rabbitGroup.add(chestMesh);
meshCatalog.chest.push(chestMesh);

// Dewlap fold
const dewlapGeom = new THREE.CylinderGeometry(0.48, 0.55, 0.25, 24);
dewlapGeom.scale(1.2, 1.0, 0.9);
const dewlapMesh = new THREE.Mesh(dewlapGeom, materials.chinchilla.body);
dewlapMesh.position.set(0, 1.15, 0.42);
dewlapMesh.rotation.x = -0.3;
dewlapMesh.castShadow = true;
rabbitGroup.add(dewlapMesh);
meshCatalog.dewlap.push(dewlapMesh);

// Head Group
const headGroup = new THREE.Group();
headGroup.position.set(0, 1.35, 0.45);
rabbitGroup.add(headGroup);

function createHeadMesh() {
  const geom = new THREE.SphereGeometry(0.68, 36, 28);
  const pos = geom.attributes.position;

  for (let i = 0; i < pos.count; i++) {
    let x = pos.getX(i);
    let y = pos.getY(i);
    let z = pos.getZ(i);

    if (z < -0.2) z *= 0.85;

    if (y < 0.1 && y > -0.5 && z > -0.2) {
      const cheekFactor = Math.exp(-(y * y) / 0.12);
      x *= (1.0 + 0.32 * cheekFactor);
    }

    if (z > 0.35 && y < 0.15) {
      x *= 0.82;
      z = 0.35 + (z - 0.35) * 0.65;
    }

    if (y > 0.2 && z > -0.1) {
      y *= 1.08;
    }

    pos.setXYZ(i, x, y, z);
  }
  geom.computeVertexNormals();

  const mesh = new THREE.Mesh(geom, materials.chinchilla.body);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  headGroup.add(mesh);
  meshCatalog.head.push(mesh);
}
createHeadMesh();

// Cheeks
[-1, 1].forEach(side => {
  const cheekGeom = new THREE.SphereGeometry(0.32, 20, 16);
  cheekGeom.scale(1.1, 0.95, 1.1);
  const cheekMesh = new THREE.Mesh(cheekGeom, materials.chinchilla.body);
  cheekMesh.position.set(side * 0.44, -0.12, 0.2);
  cheekMesh.castShadow = true;
  headGroup.add(cheekMesh);
  meshCatalog.cheeks.push(cheekMesh);
});

// Nose
const noseGeom = new THREE.SphereGeometry(0.12, 16, 12);
noseGeom.scale(1.2, 0.8, 1.0);
const noseMesh = new THREE.Mesh(noseGeom, materials.chinchilla.nose);
noseMesh.position.set(0, -0.18, 0.62);
headGroup.add(noseMesh);
meshCatalog.nose.push(noseMesh);

// Eyes
[-1, 1].forEach(side => {
  const eyeGeom = new THREE.SphereGeometry(0.14, 24, 20);
  const eyeMesh = new THREE.Mesh(eyeGeom, materials.chinchilla.eye);
  eyeMesh.position.set(side * 0.52, 0.05, 0.28);
  eyeMesh.castShadow = true;
  headGroup.add(eyeMesh);
  meshCatalog.eyes.push(eyeMesh);

  const ringGeom = new THREE.TorusGeometry(0.145, 0.025, 12, 24);
  const ringMesh = new THREE.Mesh(ringGeom, materials.chinchilla.eyeRing);
  ringMesh.position.copy(eyeMesh.position);
  ringMesh.rotation.y = side * Math.PI * 0.45;
  ringMesh.rotation.x = 0.1;
  headGroup.add(ringMesh);
  meshCatalog.eyeRings.push(ringMesh);
});

// Ears
[-1, 1].forEach(side => {
  const earGroup = new THREE.Group();
  earGroup.position.set(side * 0.22, 0.58, -0.06);
  earGroup.rotation.z = -side * 0.16;
  earGroup.rotation.x = -0.06;

  const earGeom = new THREE.CylinderGeometry(0.15, 0.19, 0.85, 20, 10, true, -Math.PI*0.4, Math.PI*1.8);
  earGeom.scale(1.0, 1.0, 0.65);
  const earMesh = new THREE.Mesh(earGeom, materials.chinchilla.ears);
  earMesh.position.y = 0.42;
  earMesh.castShadow = true;
  earGroup.add(earMesh);
  meshCatalog.ears.push(earMesh);

  const capGeom = new THREE.SphereGeometry(0.15, 16, 12);
  capGeom.scale(1.0, 0.8, 0.65);
  const capMesh = new THREE.Mesh(capGeom, materials.chinchilla.earTip);
  capMesh.position.y = 0.82;
  earGroup.add(capMesh);
  meshCatalog.earTip.push(capMesh);

  const innerGeom = new THREE.PlaneGeometry(0.18, 0.65);
  const innerMesh = new THREE.Mesh(innerGeom, materials.chinchilla.earInner);
  innerMesh.position.set(0, 0.42, 0.02);
  innerMesh.rotation.y = Math.PI;
  earGroup.add(innerMesh);
  meshCatalog.earInner.push(innerMesh);

  headGroup.add(earGroup);
});

// Thighs
[-1, 1].forEach(side => {
  const thighGeom = new THREE.SphereGeometry(0.68, 28, 22);
  thighGeom.scale(0.85, 1.15, 1.35);
  const thighMesh = new THREE.Mesh(thighGeom, materials.chinchilla.body);
  thighMesh.position.set(side * 0.72, 0.65, -0.28);
  thighMesh.rotation.y = side * 0.18;
  thighMesh.rotation.z = -side * 0.12;
  thighMesh.castShadow = true;
  thighMesh.receiveShadow = true;
  rabbitGroup.add(thighMesh);
  meshCatalog.thighs.push(thighMesh);

  const footGeom = new THREE.BoxGeometry(0.24, 0.18, 0.7);
  const footMesh = new THREE.Mesh(footGeom, materials.chinchilla.paws);
  footMesh.position.set(side * 0.62, 0.12, 0.32);
  footMesh.rotation.y = -side * 0.08;
  footMesh.castShadow = true;
  rabbitGroup.add(footMesh);
  meshCatalog.hindFeet.push(footMesh);
});

// Front Legs & Paws
[-1, 1].forEach(side => {
  const legGeom = new THREE.CylinderGeometry(0.13, 0.14, 0.65, 18);
  const legMesh = new THREE.Mesh(legGeom, materials.chinchilla.body);
  legMesh.position.set(side * 0.19, 0.42, 0.45);
  legMesh.rotation.x = -0.08;
  legMesh.castShadow = true;
  rabbitGroup.add(legMesh);
  meshCatalog.frontLegs.push(legMesh);

  const pawGeom = new THREE.BoxGeometry(0.18, 0.12, 0.32);
  const pawMesh = new THREE.Mesh(pawGeom, materials.chinchilla.paws);
  pawMesh.position.set(side * 0.19, 0.08, 0.58);
  pawMesh.castShadow = true;
  rabbitGroup.add(pawMesh);
  meshCatalog.frontPaws.push(pawMesh);
});

// Tail
const tailGeom = new THREE.ConeGeometry(0.22, 0.42, 20);
tailGeom.scale(1.0, 1.0, 0.8);
const tailMesh = new THREE.Mesh(tailGeom, materials.chinchilla.chest);
tailMesh.position.set(0, 0.48, -1.05);
tailMesh.rotation.x = -Math.PI * 0.75;
tailMesh.castShadow = true;
rabbitGroup.add(tailMesh);
meshCatalog.tail.push(tailMesh);

// Green Cushion Mat
const cushionGroup = new THREE.Group();
scene.add(cushionGroup);

const cushionMat = new THREE.MeshStandardMaterial({ color: 0x489634, roughness: 0.9, metalness: 0.02 });
const cushionRimMat = new THREE.MeshStandardMaterial({ color: 0x367325, roughness: 0.85 });

const cushionBaseGeom = new THREE.CylinderGeometry(1.65, 1.75, 0.14, 40);
cushionBaseGeom.scale(1.0, 1.0, 1.18);
const cushionBase = new THREE.Mesh(cushionBaseGeom, cushionMat);
cushionBase.position.y = -0.07;
cushionBase.receiveShadow = true;
cushionGroup.add(cushionBase);

const rimGeom = new THREE.TorusGeometry(1.68, 0.08, 16, 48);
rimGeom.scale(1.0, 1.18, 0.8);
rimGeom.rotateX(Math.PI * 0.5);
const rimMesh = new THREE.Mesh(rimGeom, cushionRimMat);
rimMesh.position.y = 0.0;
cushionGroup.add(rimMesh);

const stemGeom = new THREE.CylinderGeometry(0.06, 0.08, 0.45, 12);
stemGeom.rotateZ(Math.PI * 0.35);
const stemMesh = new THREE.Mesh(stemGeom, cushionRimMat);
stemMesh.position.set(-1.75, 0.02, -0.6);
cushionGroup.add(stemMesh);

// Floor & Helpers
const planeGeom = new THREE.PlaneGeometry(25, 25);
const planeMat = new THREE.ShadowMaterial({ opacity: 0.35 });
const shadowPlane = new THREE.Mesh(planeGeom, planeMat);
shadowPlane.rotation.x = -Math.PI * 0.5;
shadowPlane.position.y = -0.141;
shadowPlane.receiveShadow = true;
scene.add(shadowPlane);

const gridHelper = new THREE.GridHelper(12, 24, 0x556070, 0x28303e);
gridHelper.position.y = -0.14;
scene.add(gridHelper);

const symGeom = new THREE.PlaneGeometry(3.2, 3.0);
const symMat = new THREE.MeshBasicMaterial({ color: 0x33bbff, transparent: true, opacity: 0.18, side: THREE.DoubleSide });
const symPlane = new THREE.Mesh(symGeom, symMat);
symPlane.rotation.y = Math.PI * 0.5;
symPlane.position.set(0, 1.2, 0);
symPlane.visible = false;
scene.add(symPlane);

// --- 6. Anatomy Pins ---
const anatomyPins = [
  { id: 1, name: "1. 耳（直立短耳）", pos: new THREE.Vector3(0, 2.3, 0.38), camPos: new THREE.Vector3(0.5, 2.3, 1.6), target: new THREE.Vector3(0, 1.9, 0.4) },
  { id: 2, name: "2. クラウン・頭部", pos: new THREE.Vector3(0, 1.85, 0.75), camPos: new THREE.Vector3(0, 1.6, 2.2), target: new THREE.Vector3(0, 1.35, 0.5) },
  { id: 3, name: "3. 側面の大きな目", pos: new THREE.Vector3(0.68, 1.4, 0.72), camPos: new THREE.Vector3(1.8, 1.4, 1.6), target: new THREE.Vector3(0.3, 1.35, 0.4) },
  { id: 4, name: "4. 首元・胸肉", pos: new THREE.Vector3(0, 1.0, 0.85), camPos: new THREE.Vector3(0, 0.9, 2.4), target: new THREE.Vector3(0, 0.9, 0.4) },
  { id: 5, name: "5. 背中のCカーブ", pos: new THREE.Vector3(0, 1.75, -0.35), camPos: new THREE.Vector3(2.5, 1.6, -0.2), target: new THREE.Vector3(0, 1.2, -0.2) },
  { id: 6, name: "6. 揃った前足", pos: new THREE.Vector3(0, 0.25, 0.85), camPos: new THREE.Vector3(0.6, 0.4, 2.0), target: new THREE.Vector3(0, 0.2, 0.5) },
  { id: 7, name: "7. 大腿筋塊・太もも", pos: new THREE.Vector3(0.95, 0.7, -0.25), camPos: new THREE.Vector3(2.4, 0.9, 0.6), target: new THREE.Vector3(0.4, 0.6, -0.2) },
  { id: 8, name: "8. 尻尾の収まり", pos: new THREE.Vector3(0, 0.5, -1.35), camPos: new THREE.Vector3(0, 0.8, -2.5), target: new THREE.Vector3(0, 0.5, -0.8) }
];

const pinElements = [];
anatomyPins.forEach(p => {
  const el = document.createElement('div');
  el.className = 'pin-label';
  el.textContent = p.name;
  el.addEventListener('click', () => focusPin(p));
  pinsContainer.appendChild(el);
  pinElements.push({ data: p, el: el });
});

function updatePins() {
  if (!document.getElementById('toggle-pins').checked) {
    pinsContainer.style.display = 'none';
    return;
  }
  pinsContainer.style.display = 'block';

  const tempV = new THREE.Vector3();
  const halfW = container.clientWidth * 0.5;
  const halfH = container.clientHeight * 0.5;

  pinElements.forEach(item => {
    tempV.copy(item.data.pos);
    tempV.project(camera);

    if (tempV.z > 1) {
      item.el.style.display = 'none';
      return;
    }

    const x = (tempV.x * halfW) + halfW;
    const y = -(tempV.y * halfH) + halfH;
    item.el.style.display = 'block';
    item.el.style.left = `${x}px`;
    item.el.style.top = `${y}px`;
  });
}

// --- 7. Material Modes ---
function setRenderMode(mode) {
  document.querySelectorAll('.mode-btn').forEach(btn => {
    btn.classList.toggle('active', btn.getAttribute('data-mode') === mode);
  });

  const applyMat = (meshes, mat, wire = false) => {
    meshes.forEach(m => {
      m.material = mat;
      m.material.wireframe = wire;
    });
  };

  if (mode === 'chinchilla') {
    applyMat(meshCatalog.torso, materials.chinchilla.body);
    applyMat(meshCatalog.head, materials.chinchilla.body);
    applyMat(meshCatalog.cheeks, materials.chinchilla.body);
    applyMat(meshCatalog.thighs, materials.chinchilla.body);
    applyMat(meshCatalog.dewlap, materials.chinchilla.body);
    applyMat(meshCatalog.chest, materials.chinchilla.chest);
    applyMat(meshCatalog.tail, materials.chinchilla.chest);
    applyMat(meshCatalog.frontLegs, materials.chinchilla.body);
    applyMat(meshCatalog.frontPaws, materials.chinchilla.paws);
    applyMat(meshCatalog.hindFeet, materials.chinchilla.paws);
    applyMat(meshCatalog.ears, materials.chinchilla.ears);
    applyMat(meshCatalog.earInner, materials.chinchilla.earInner);
    applyMat(meshCatalog.earTip, materials.chinchilla.earTip);
    applyMat(meshCatalog.eyes, materials.chinchilla.eye);
    applyMat(meshCatalog.eyeRings, materials.chinchilla.eyeRing);
    applyMat(meshCatalog.nose, materials.chinchilla.nose);
  } else if (mode === 'clay') {
    Object.values(meshCatalog).flat().forEach(m => {
      m.material = materials.clay;
      m.material.wireframe = false;
    });
  } else if (mode === 'terracotta') {
    Object.values(meshCatalog).flat().forEach(m => {
      m.material = materials.terracotta;
      m.material.wireframe = false;
    });
  } else if (mode === 'paperclay') {
    Object.values(meshCatalog).flat().forEach(m => {
      m.material = materials.paperclay;
      m.material.wireframe = false;
    });
  } else if (mode === 'wireframe') {
    Object.values(meshCatalog).flat().forEach(m => {
      m.material = materials.clay;
      m.material.wireframe = true;
    });
  } else if (mode === 'blocking') {
    applyMat(meshCatalog.torso, materials.blocking.torso);
    applyMat(meshCatalog.head, materials.blocking.head);
    applyMat(meshCatalog.cheeks, materials.blocking.cheeks);
    applyMat(meshCatalog.ears, materials.blocking.ears);
    applyMat(meshCatalog.earInner, materials.blocking.ears);
    applyMat(meshCatalog.earTip, materials.blocking.ears);
    applyMat(meshCatalog.eyes, materials.chinchilla.eye);
    applyMat(meshCatalog.eyeRings, materials.blocking.head);
    applyMat(meshCatalog.nose, materials.blocking.cheeks);
    applyMat(meshCatalog.dewlap, materials.blocking.dewlap);
    applyMat(meshCatalog.chest, materials.blocking.dewlap);
    applyMat(meshCatalog.thighs, materials.blocking.thighs);
    applyMat(meshCatalog.frontLegs, materials.blocking.frontLegs);
    applyMat(meshCatalog.frontPaws, materials.blocking.paws);
    applyMat(meshCatalog.hindFeet, materials.blocking.hindFeet);
    applyMat(meshCatalog.tail, materials.blocking.tail);
  }
}

document.querySelectorAll('.mode-btn').forEach(btn => {
  btn.addEventListener('click', () => setRenderMode(btn.getAttribute('data-mode')));
});

// --- 8. Presets & Animation ---
let targetCamPos = null;
let targetLookAt = null;

function animateCameraTo(camPos, lookAt) {
  targetCamPos = camPos.clone();
  targetLookAt = lookAt.clone();
}

const viewPresets = {
  photo: { cam: new THREE.Vector3(2.5, 1.45, 1.7), target: new THREE.Vector3(0, 0.95, 0.1) },
  front: { cam: new THREE.Vector3(0, 1.2, 3.2), target: new THREE.Vector3(0, 0.95, 0.3) },
  right: { cam: new THREE.Vector3(3.2, 1.1, 0), target: new THREE.Vector3(0, 0.95, 0) },
  left: { cam: new THREE.Vector3(-3.2, 1.1, 0), target: new THREE.Vector3(0, 0.95, 0) },
  back: { cam: new THREE.Vector3(0, 1.3, -3.2), target: new THREE.Vector3(0, 0.95, -0.1) },
  top: { cam: new THREE.Vector3(0, 4.0, 0.01), target: new THREE.Vector3(0, 0.8, 0) },
  bottom: { cam: new THREE.Vector3(0, -2.8, 0.01), target: new THREE.Vector3(0, 0.6, 0) },
  quarter: { cam: new THREE.Vector3(2.3, 1.6, 2.3), target: new THREE.Vector3(0, 0.95, 0.1) }
};

document.querySelectorAll('.preset-btn[data-view]').forEach(btn => {
  btn.addEventListener('click', () => {
    const viewKey = btn.getAttribute('data-view');
    const p = viewPresets[viewKey];
    if (p) {
      animateCameraTo(p.cam, p.target);
      document.querySelectorAll('.preset-btn[data-view]').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
    }
  });
});

let isTurntable = false;
const btnTurntable = document.getElementById('btn-turntable');
btnTurntable.addEventListener('click', () => {
  isTurntable = !isTurntable;
  btnTurntable.classList.toggle('active', isTurntable);
  controls.autoRotate = isTurntable;
  controls.autoRotateSpeed = 1.8;
});

document.getElementById('btn-reset-cam').addEventListener('click', () => {
  animateCameraTo(viewPresets.photo.cam, viewPresets.photo.target);
  controls.autoRotate = false;
  btnTurntable.classList.remove('active');
});

function focusPin(pin) {
  animateCameraTo(pin.camPos, pin.target);
  document.querySelectorAll('.point-card').forEach(card => {
    const match = card.getAttribute('data-pin') == pin.id;
    card.classList.toggle('active', match);
    if (match) {
      card.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  });
  switchTab('tab-anatomy');
}

document.querySelectorAll('.point-card').forEach(card => {
  card.addEventListener('click', () => {
    const pinId = parseInt(card.getAttribute('data-pin'));
    const pin = anatomyPins.find(p => p.id === pinId);
    if (pin) focusPin(pin);
  });
});

// --- 9. Tabs ---
function switchTab(tabId) {
  document.querySelectorAll('.tab-nav-btn').forEach(btn => {
    btn.classList.toggle('active', btn.getAttribute('data-tab') === tabId);
  });
  document.querySelectorAll('.tab-pane').forEach(pane => {
    pane.classList.toggle('active', pane.id === tabId);
  });
}

document.querySelectorAll('.tab-nav-btn').forEach(btn => {
  btn.addEventListener('click', () => switchTab(btn.getAttribute('data-tab')));
});

// --- 10. Light & Slicing Events ---
const inAzimuth = document.getElementById('light-azimuth');
const inElevation = document.getElementById('light-elevation');
const inIntensity = document.getElementById('light-intensity');
const inAmbient = document.getElementById('light-ambient');

inAzimuth.addEventListener('input', () => {
  document.getElementById('val-azimuth').textContent = `${inAzimuth.value}°`;
  updateLightPosition();
});
inElevation.addEventListener('input', () => {
  document.getElementById('val-elevation').textContent = `${inElevation.value}°`;
  updateLightPosition();
});
inIntensity.addEventListener('input', () => {
  document.getElementById('val-intensity').textContent = inIntensity.value;
  mainLight.intensity = parseFloat(inIntensity.value);
});
inAmbient.addEventListener('input', () => {
  document.getElementById('val-ambient').textContent = inAmbient.value;
  ambientLight.intensity = parseFloat(inAmbient.value);
});

const toggleSlicer = document.getElementById('toggle-slicer');
const sliceHeight = document.getElementById('slice-height');
const slicerControls = document.getElementById('slicer-controls');

toggleSlicer.addEventListener('change', () => {
  const enabled = toggleSlicer.checked;
  renderer.clippingPlanes = enabled ? [clipPlane] : [];
  slicerControls.style.opacity = enabled ? '1' : '0.5';
  slicerControls.style.pointerEvents = enabled ? 'auto' : 'none';
});

sliceHeight.addEventListener('input', () => {
  const val = parseFloat(sliceHeight.value);
  document.getElementById('val-slice').textContent = `${val.toFixed(2)}m`;
  clipPlane.constant = val;
});

document.getElementById('toggle-grid').addEventListener('change', (e) => {
  gridHelper.visible = e.target.checked;
  shadowPlane.visible = e.target.checked;
});
document.getElementById('toggle-cushion').addEventListener('change', (e) => {
  cushionGroup.visible = e.target.checked;
});
document.getElementById('toggle-symmetry').addEventListener('change', (e) => {
  symPlane.visible = e.target.checked;
});

document.getElementById('btn-snapshot').addEventListener('click', () => {
  renderer.render(scene, camera);
  const url = renderer.domElement.toDataURL('image/png');
  const a = document.createElement('a');
  a.href = url;
  a.download = `netherland_dwarf_clay_reference_${Date.now()}.png`;
  a.click();
});

window.addEventListener('resize', () => {
  camera.aspect = container.clientWidth / container.clientHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(container.clientWidth, container.clientHeight);
});

function animate() {
  requestAnimationFrame(animate);

  if (targetCamPos && targetLookAt) {
    camera.position.lerp(targetCamPos, 0.08);
    controls.target.lerp(targetLookAt, 0.08);
    if (camera.position.distanceTo(targetCamPos) < 0.02 && controls.target.distanceTo(targetLookAt) < 0.02) {
      targetCamPos = null;
      targetLookAt = null;
    }
  }

  controls.update();
  renderer.render(scene, camera);
  updatePins();
}
animate();
